let fs, JSDOM;const origin='https://thecalculatorshouse.com';const out='docs/live-qa-2026-10-24/';const locales=['en-us','en-gb','de-de','fr-fr','es-es','pt-br','ru-ru','tr-tr','ja-jp','zh-cn','it-it','nl-nl'];const bodies=new Map();
async function get(path,method='GET'){const url=path.startsWith('http')?path:origin+path;const start=performance.now();try{const r=await fetch(url,{method,redirect:'manual',signal:AbortSignal.timeout(25000),headers:{'User-Agent':'CalculatorHouse-QA/2026-10-24','Accept-Encoding':'gzip, br'}});const ttfb=performance.now()-start;const body=method==='GET'?await r.text():'';const headers=Object.fromEntries(r.headers);delete headers['set-cookie'];return {path,url,status:r.status,ttfbMs:Math.round(ttfb),durationMs:Math.round(performance.now()-start),decodedBytes:Buffer.byteLength(body),headers,body};}catch(e){return{path,url,error:e.message}}}
async function mapLimit(items,fn,n=3){const result=new Array(items.length);let next=0;await Promise.all(Array.from({length:n},async()=>{while(next<items.length){const i=next++;result[i]=await fn(items[i],i);}}));return result;}
function analyze(r){if(r.status!==200||!r.headers['content-type']?.includes('text/html'))return {...r,body:undefined};bodies.set(r.path,r.body);const dom=new JSDOM(r.body),d=dom.window.document;const schemas=[...d.querySelectorAll('script[type="application/ld+json"]')].map(x=>{try{return JSON.parse(x.textContent)}catch{return{parseError:true}}});const walk=x=>Array.isArray(x)?x.flatMap(walk):x&&typeof x==='object'?[x,...Object.values(x).flatMap(walk)]:[];const nodes=schemas.flatMap(walk);const canonical=d.querySelector('link[rel="canonical"]')?.href;const links=[...d.querySelectorAll('link[rel="alternate"][hreflang]')].map(x=>({lang:x.hreflang,href:x.href}));const assets=[...d.querySelectorAll('script[src],link[rel="stylesheet"][href]')].map(x=>x.src||x.href);const cspMeta=d.querySelector('meta[http-equiv="Content-Security-Policy"]')?.content??null;const sourceLinks=[...d.querySelectorAll('main a[href^="https:"]')].map(x=>x.href);const result={...r,body:undefined,title:d.title,description:d.querySelector('meta[name="description"]')?.content,canonical,canonicalSelf:canonical===r.url,lang:d.documentElement.lang,h1:[...d.querySelectorAll('h1')].map(x=>x.textContent.trim()),robots:d.querySelector('meta[name="robots"]')?.content,alternates:links,schemaTypes:[...new Set(nodes.flatMap(x=>x['@type']??[]))],schemaParseErrors:schemas.filter(x=>x.parseError).length,faqQuestions:nodes.filter(x=>x['@type']==='Question').map(x=>x.name),articleDates:nodes.filter(x=>x['@type']==='Article').map(x=>({published:x.datePublished,modified:x.dateModified})),citations:nodes.filter(x=>x.citation).map(x=>x.citation),sourceLinks,cspMeta,manualAdWrappers:d.querySelectorAll('aside.ad-wrap').length,adScript:assets.some(x=>x.includes('adsbygoogle.js')),assets,inlineBytes:[...d.querySelectorAll('script:not([src])')].reduce((n,x)=>n+Buffer.byteLength(x.textContent),0),mainTextChars:d.querySelector('main')?.textContent.length??0,images:[...d.querySelectorAll('img')].map(x=>({src:x.src,alt:x.getAttribute('alt'),width:x.getAttribute('width'),height:x.getAttribute('height')}))};dom.window.close();return result;}
(async()=>{fs=await import('node:fs');({JSDOM}=await import('jsdom'));const patterns=['','/calculators/finance/loan','/tools/number-math/percentage','/charts/math/metric-prefixes','/guides/what-is/what-is-compound-interest','/privacy'];const paths=locales.flatMap(l=>patterns.map(p=>'/'+l+p)).concat(['/en-us/calculators/construction/concrete','/en-us/calculators/education/gpa','/en-us/countries/ca/income-tax','/en-us/countries/fr/salary','/en-us/converters/volume/liters-to-us-gallons','/en-us/tools/planning/savings-goal','/en-us/about','/en-us/contact']);const pages=await mapLimit(paths,async p=>analyze(await get(p)));console.log('HTML samples:',pages.length,'200:',pages.filter(x=>x.status===200).length);fs.writeFileSync(out+'pages.json',JSON.stringify({checkedAt:new Date().toISOString(),method:'Bounded public GET samples, concurrency 3, no JS execution or ad requests',pages},null,2));
const resources=await mapLimit(['/robots.txt','/ads.txt','/llms.txt','/sitemap.xml','/.well-known/release.json'],p=>get(p));const sitemapIndex=resources.find(x=>x.path==='/sitemap.xml');const sitemapUrls=[...(sitemapIndex.body??'').matchAll(/<loc>(.*?)<\/loc>/g)].map(x=>x[1]);const sitemaps=await mapLimit(sitemapUrls,async url=>{const r=await get(url);return {...r,body:undefined,urls:[...(r.body??'').matchAll(/<loc>(.*?)<\/loc>/g)].map(x=>x[1].replaceAll('&amp;','&'))};});const sitemapAll=sitemaps.flatMap(x=>x.urls);fs.writeFileSync(out+'discovery.json',JSON.stringify({checkedAt:new Date().toISOString(),resources,sitemaps,totalUrls:sitemapAll.length,duplicateUrls:sitemapAll.filter((x,i)=>sitemapAll.indexOf(x)!==i)},null,2));console.log('Sitemaps:',sitemaps.length,'URLs:',sitemapAll.length);
const security=await mapLimit(['/.env','/.git/config','/package.json','/next.config.ts','/en-us/qa-missing-20261024','/hi-in','/gu-in','/mr-in','/ar-ae','/pl-pl','http://thecalculatorshouse.com/en-us','https://www.thecalculatorshouse.com/en-us'],async p=>{const r=await get(p);return {...r,body:undefined,looksLikeSecret:r.status===200&&(p==='/.env'||p==='/.git/config')?/(?:\[core\]|(?:SECRET|PASSWORD|TOKEN)=)/i.test(r.body):false}});fs.writeFileSync(out+'security.json',JSON.stringify({checkedAt:new Date().toISOString(),method:'Nonintrusive public GET only; sensitive-looking response bodies are not stored',security},null,2));
const home=pages.find(x=>x.path==='/en-us'),loan=pages.find(x=>x.path==='/en-us/calculators/finance/loan');const assetUrls=[...new Set([...home.assets,...loan.assets].map(x=>new URL(x,origin).href))].filter(x=>x.startsWith(origin)&&/\.(?:js|css)(?:\?|$)/.test(x));const assets=await mapLimit(assetUrls,async url=>{const r=await get(url);return{url,status:r.status,decodedBytes:r.decodedBytes,ttfbMs:r.ttfbMs,durationMs:r.durationMs,contentLength:r.headers?.['content-length'],encoding:r.headers?.['content-encoding'],cache:r.headers?.['cache-control'],sourceMapComment:/sourceMappingURL=/.test(r.body??'')};});fs.writeFileSync(out+'assets.json',JSON.stringify({checkedAt:new Date().toISOString(),method:'HTTP transfer observations from this location; not CWV or a load test',assets},null,2));console.log('Assets:',assets.length,'decoded bytes:',assets.reduce((n,x)=>n+(x.decodedBytes||0),0));
const findings=pages.filter(x=>x.status!==200||!x.title||x.h1?.length!==1||!x.canonicalSelf||x.schemaParseErrors);console.log('Metadata exceptions:',JSON.stringify(findings.map(x=>({path:x.path,status:x.status,h1:x.h1?.length,canonical:x.canonical,error:x.error}))));
for(const strategy of ['mobile','desktop']){try{const r=await get('https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url='+encodeURIComponent(origin+'/en-us')+'&strategy='+strategy+'&category=performance');let body;try{body=JSON.parse(r.body)}catch{body={error:r.error??'non-json'}};fs.writeFileSync(out+'pagespeed-'+strategy+'.json',JSON.stringify({checkedAt:new Date().toISOString(),status:r.status,result:body},null,2));console.log('PageSpeed',strategy,r.status,body.error?.message??'');}catch(e){console.log('PageSpeed',strategy,e.message)}}
})();
